import {CITY,KINDS,ERAS,esc,name,description,fixture,filter,validate,project,fit,zoom,clampBounds} from "./assets/engine.js";import {texts} from "./assets/language.js";
const $=id=>document.getElementById(id),icon=id=>`<svg aria-hidden="true"><use href="./assets/icons.svg#${id}"></use></svg>`;let records=fixture(),lang="en",selected="gate",bounds={...CITY},editing=null,baseline="",pending=null,toastTimer,zone="local",drag=null;const t=key=>texts[lang][key]||key;
function toast(key){$("toast").textContent=t(key);$("toast").hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$("toast").hidden=true,2800);}
function visible(){return filter(records,{query:$("search").value,kind:$("kind").value,era:$("era").value,sort:$("sort").value,lang});}
function options(element,items,allKey=null){const previous=element.value;element.innerHTML=(allKey?`<option value="">${esc(t(allKey))}</option>`:"")+items.map(value=>`<option value="${value}">${esc(t(ERAS.includes(value)?"century"+value:value))}</option>`).join("");if([...element.options].some(option=>option.value===previous))element.value=previous;}
function localize(){
  document.documentElement.lang=lang;document.title=lang==="en"?"avarc — History has a place":"avarc — Geschichte hat einen Ort";document.querySelector("meta[name=description]").content=lang==="en"?"A bilingual historical place archive with a local editor and original schematic map.":"Ein zweisprachiges Ortsarchiv mit lokalem Editor und eigenem Kartenschema.";
  document.querySelectorAll("[data-i18n]").forEach(node=>node.textContent=t(node.dataset.i18n));document.querySelectorAll("[data-i18n-placeholder]").forEach(node=>node.placeholder=t(node.dataset.i18nPlaceholder));document.querySelectorAll("[data-i18n-aria]").forEach(node=>node.setAttribute("aria-label",t(node.dataset.i18nAria)));document.querySelectorAll("[data-lang]").forEach(button=>button.setAttribute("aria-pressed",button.dataset.lang===lang));document.querySelector("nav").setAttribute("aria-label",lang==="en"?"Main navigation":"Hauptnavigation");document.querySelector(".header-end .language").setAttribute("aria-label",lang==="en"?"Language":"Sprache");document.querySelector(".workspace").setAttribute("aria-label",t("local"));$("map-accessible-title").textContent=lang==="en"?"Historical place coordinate diagram":"Koordinatendiagramm historischer Orte";
  options($("kind"),KINDS,"allKinds");options($("era"),ERAS,"allEras");options($("record-kind"),KINDS);options($("record-era"),ERAS);render();
}
function render(){
  const list=visible();if(!list.some(record=>record.id===selected))selected=list[0]?.id||null;$("total-count").textContent=records.length;$("chapter-title").textContent=records.length===6?t("chapterTitle"):lang==="en"?`${records.length} places. Countless stories.`:`${records.length} Orte. Unzählige Geschichten.`;$("result-count").textContent=`${list.length} ${t("results")}`;$("places").innerHTML=list.length?list.map(record=>`<article class="place-card ${record.id===selected?"selected":""}" data-record="${esc(record.id)}"><div class="place-thumb"><img src="./assets/${record.art}.svg" alt="" loading="lazy"></div><div><span class="place-kind">${esc(t(record.kind))} / ${esc(t("century"+record.era))}</span><h3><button data-select="${esc(record.id)}" aria-pressed="${record.id===selected}">${esc(name(record,lang))}</button></h3><p>${esc(description(record,lang))}</p></div></article>`).join(""):`<div class="empty"><h3>${t("none")}</h3><p>${t("noneHelp")}</p><button class="outline" id="clear">${t("clear")}</button></div>`;renderMap();renderDetail();
}
function renderMap(){
  const start=project({lon:CITY.west,lat:CITY.north},bounds),end=project({lon:CITY.east,lat:CITY.south},bounds);$("map-art").innerHTML=`<image href="./assets/city.svg" x="${start.x}" y="${start.y}" width="${end.x-start.x}" height="${end.y-start.y}" preserveAspectRatio="none"/>`;
  $("map-pins").innerHTML=visible().map((record,index)=>{const{x,y}=project(record,bounds);return x< -20||x>1020||y< -20||y>620?"":`<g class="marker ${record.id===selected?"selected":""}" data-pin="${esc(record.id)}" role="button" tabindex="0" aria-label="${esc(t("select")+": "+name(record,lang))}" aria-pressed="${record.id===selected}" transform="translate(${x} ${y})"><circle r="19"/><text text-anchor="middle" dy="5">${index+1}</text></g>`;}).join("");const cityView=bounds.east>=CITY.west&&bounds.west<=CITY.east&&bounds.north>=CITY.south&&bounds.south<=CITY.north&&bounds.east-bounds.west<=.3&&bounds.north-bounds.south<=.15;$("map-mode").textContent=t(cityView?"cityMap":"grid");$("map-coordinates").textContent=`${((bounds.north+bounds.south)/2).toFixed(3)}°, ${((bounds.west+bounds.east)/2).toFixed(3)}°`;
}
function renderDetail(){
  const record=records.find(item=>item.id===selected);if(!record){$("selected-place").innerHTML="";return;}const actualZone=zone==="local"?Intl.DateTimeFormat().resolvedOptions().timeZone:zone,formatted=new Intl.DateTimeFormat(lang==="en"?"en-GB":"de-DE",{dateStyle:"medium",timeStyle:"short",timeZone:actualZone}).format(new Date(record.updatedAt));
  $("selected-place").innerHTML=`<article class="selected-detail"><img class="selected-art" src="./assets/${record.art}.svg" alt=""><div class="detail-copy"><span class="eyebrow">${t("record")}</span><h3 id="selected-title">${esc(name(record,lang))}</h3><p>${esc(description(record,lang))}</p><p class="detail-coordinates">${record.lat.toFixed(5)}° / ${record.lon.toFixed(5)}°</p><div class="detail-actions"><button id="locate">${icon("locate")}${t("locate")}</button><button id="edit">${icon("edit")}${t("edit")}</button><button class="delete" id="delete">${icon("trash")}${t("remove")}</button></div><div class="record-time"><span>${t("updated")}</span><time datetime="${record.updatedAt}">${esc(formatted)} · ${esc(actualZone)}</time><label class="zone">${t("timeZone")}<select id="zone"><option value="local">${t("localTime")}</option><option value="UTC">UTC</option><option value="Europe/Berlin">Berlin</option></select></label></div></div></article>`;$("zone").value=zone;$("zone").addEventListener("change",event=>{zone=event.target.value;renderDetail();$("zone").focus();});$("locate").addEventListener("click",()=>{bounds=fit([record]);renderMap();});$("edit").addEventListener("click",()=>openEditor(record));$("delete").addEventListener("click",()=>ask("deleteTitle","deleteCopy","cancel","confirmDelete",()=>{records=records.filter(item=>item.id!==record.id);selected=null;render();toast("deleted");($("places").querySelector("button")||$("add")).focus();}));
}
function choose(id,focusMap=false){selected=id;render();document.querySelector(focusMap?`[data-pin="${id}"]`:`[data-select="${id}"]`)?.focus({preventScroll:true});}
function snapshot(){return JSON.stringify([...new FormData($("record-form")).entries()]);}
function openEditor(record=null){
  if(!record&&records.length>=20){toast("limit");return;}editing=record?.id||null;$("record-form").reset();$("form-error").textContent="";const form=$("record-form").elements;form.enName.value=record?.names.en||"";form.deName.value=record?.names.de||"";form.enText.value=record?.descriptions.en||"";form.deText.value=record?.descriptions.de||"";form.lat.value=record?.lat??"";form.lon.value=record?.lon??"";form.kind.value=record?.kind||KINDS[0];form.era.value=record?.era||"20";$("editor-title").textContent=t(record?"editTitle":"newTitle");baseline=snapshot();$("editor").showModal();$("editor").scrollTop=0;
}
function ask(title,copy,keep,confirm,action){pending=action;$("confirm-title").textContent=t(title);$("confirm-copy").textContent=t(copy);$("confirm-keep").textContent=t(keep);$("confirm-action").textContent=t(confirm);$("confirm-dialog").showModal();}
function closeEditor(){if(snapshot()!==baseline)ask("leaveTitle","leaveCopy","keep","discard",()=>{$("editor").close();$("record-form").reset();});else $("editor").close();}
$("record-form").addEventListener("submit",event=>{event.preventDefault();if(!$("editor").open)return;try{const old=records.find(record=>record.id===editing);if(editing&&!old)throw Error("classification");if(!old&&records.length>=20){toast("limit");return;}const value=validate({...Object.fromEntries(new FormData(event.currentTarget)),id:crypto.randomUUID()},old);records=old?records.map(record=>record.id===old.id?value:record):[...records,value];selected=value.id;$("search").value="";$("kind").value="";$("era").value="";bounds=fit([value]);$("editor").close();render();toast("saved");$("edit").focus();}catch(error){$("form-error").textContent=t("error"+error.message[0].toUpperCase()+error.message.slice(1));}});
$("editor-close").addEventListener("click",closeEditor);$("editor").addEventListener("cancel",event=>{event.preventDefault();closeEditor();});$("confirm-action").addEventListener("click",()=>{const action=pending;pending=null;$("confirm-dialog").close();action?.();});$("add").addEventListener("click",()=>openEditor());document.addEventListener("click",event=>{const target=event.target.closest("button,[data-pin]");if(!target)return;if(target.hasAttribute("data-select"))choose(target.dataset.select);if(target.hasAttribute("data-pin"))choose(target.dataset.pin,true);if(target.hasAttribute("data-lang")){lang=target.dataset.lang;localize();}if(target.hasAttribute("data-scope"))$("scope").showModal();if(target.hasAttribute("data-close"))$(target.dataset.close).close();if(target.id==="clear"){$("search").value="";$("kind").value="";$("era").value="";$("sort").value="name";selected=null;render();bounds=fit(visible());renderMap();}});
$("map").addEventListener("keydown",event=>{const pin=event.target.closest("[data-pin]");if(pin&&["Enter"," "].includes(event.key)){event.preventDefault();choose(pin.dataset.pin,true);}});$("search").addEventListener("input",()=>{render();bounds=fit(visible());renderMap();});for(const id of ["kind","era","sort"])$(id).addEventListener("change",()=>{render();bounds=fit(visible());renderMap();});$("zoom-in").addEventListener("click",()=>{bounds=zoom(bounds,.7);renderMap();});$("zoom-out").addEventListener("click",()=>{bounds=zoom(bounds,1/.7);renderMap();});$("fit").addEventListener("click",()=>{bounds=fit(visible());renderMap();});$("reset-map").addEventListener("click",()=>{bounds={...CITY};renderMap();});
const map=$("map");map.addEventListener("pointerdown",event=>{if(event.pointerType!=="mouse"||event.button!==0||event.target.closest("[data-pin]"))return;const point=new DOMPoint(event.clientX,event.clientY).matrixTransform(map.getScreenCTM().inverse());drag={id:event.pointerId,x:point.x,y:point.y,bounds:{...bounds}};map.setPointerCapture(event.pointerId);map.classList.add("dragging");});map.addEventListener("pointermove",event=>{if(!drag||drag.id!==event.pointerId)return;const point=new DOMPoint(event.clientX,event.clientY).matrixTransform(map.getScreenCTM().inverse()),dx=-(point.x-drag.x)/920*(drag.bounds.east-drag.bounds.west),dy=(point.y-drag.y)/520*(drag.bounds.north-drag.bounds.south);bounds=clampBounds({west:drag.bounds.west+dx,east:drag.bounds.east+dx,south:drag.bounds.south+dy,north:drag.bounds.north+dy});renderMap();});function endDrag(){drag=null;map.classList.remove("dragging");}map.addEventListener("pointerup",endDrag);map.addEventListener("pointercancel",endDrag);map.addEventListener("lostpointercapture",endDrag);localize();
